-- CRM 321: herramientas nuevas al catálogo y habilidades reales de las existentes.
-- Las habilidades se destacan ante el cliente sin costo y van aparte de las características: no entran al alcance del acuerdo.
alter table catalogo add column if not exists habilidades_es text[] not null default '{}';
alter table catalogo add column if not exists habilidades_en text[] not null default '{}';

insert into catalogo
  (codigo, tipo, categoria, nombre_es, nombre_en, descripcion_es, descripcion_en, caracteristicas_es, caracteristicas_en, resuelve, incluye, precio_setup, precio_mensual, costo_setup, costo_mensual, usuarios_incluidos, volumen, semanas, estado, orden)
values
('FABRICA_REELS', 'modulo', 'marketing', 'Fábrica de reels con IA', 'AI reel factory', 'Produce reels completos sin cámara: guion, voz, música, subtítulos y portada, con el estilo de tu marca y revisión de calidad automática antes de publicar.', 'Produces complete reels without a camera: script, voice, music, subtitles and cover, in your brand style with automatic quality review before publishing.', array['4 formatos por código: POV, mito vs realidad, lista y proceso', 'Reels de tipografía cinética y de datos', 'Montaje con tus propias fotos y videos', 'Reels de cualquier tema, de 10 a 180 segundos', 'Series de 2 a 6 partes, con votación del público', 'Voces naturales, música original y efectos de sonido', 'Subtítulos palabra por palabra y portadas', 'Recrear el estilo de un reel de referencia', 'Revisión automática: sin segundos quietos ni frases de relleno', 'Marca de agua móvil y reglas propias de tu marca', 'Consumo de IA y mensajería con tus propias cuentas, sin límites de cupo']::text[], array['4 coded formats: POV, myth vs reality, list and process', 'Kinetic typography and data reels', 'Montage with your own photos and videos', 'Reels on any topic, 10 to 180 seconds', '2 to 6 part series, with audience voting', 'Natural voices, original music and sound effects', 'Word-by-word subtitles and covers', 'Recreate the style of a reference reel', 'Automatic review: no dead seconds or filler phrases', 'Moving watermark and your own brand rules', 'AI and messaging usage on your own accounts, no quota limits']::text[], array['no publican contenido', 'sin tiempo para redes', 'reels', 'contenido en video', 'community manager caro', 'redes inconsistentes']::text[], '{}', 2200, 390, 600, 60, 0, null, 3, 'listo', 210),
('FABRICA_CARRUSELES', 'modulo', 'marketing', 'Fábrica de carruseles e historias', 'Carousel and stories factory', 'Carruseles y historias de Instagram y Facebook hechos con código, medidos y revisados antes de salir, con 11 estilos y tu marca.', 'Instagram and Facebook carousels and stories built with code, measured and reviewed before they go out, with 11 styles and your brand.', array['Carruseles 4:5 o 1:1 de 2 a 10 láminas', 'Carrusel hermano de cada reel, con el mismo guion', '11 estilos de carrusel, uno por cada estilo de reel', 'Historias de Instagram y Facebook en foto y video 9:16', 'Revisión automática: márgenes, contraste, tamaño de letra, ortografía y texto alternativo', 'Recrear un carrusel de referencia con tu estilo', 'Noticias del día convertidas en contenido', 'Consumo de IA y mensajería con tus propias cuentas, sin límites de cupo']::text[], array['4:5 or 1:1 carousels of 2 to 10 slides', 'A sibling carousel for each reel, same script', '11 carousel styles, one per reel style', 'Instagram and Facebook stories in 9:16 photo and video', 'Automatic review: margins, contrast, font size, spelling and alt text', 'Recreate a reference carousel in your style', 'Daily news turned into content', 'AI and messaging usage on your own accounts, no quota limits']::text[], array['no publican contenido', 'redes abandonadas', 'carruseles', 'historias', 'poco alcance en redes']::text[], '{}', 1200, 190, 300, 30, 0, null, 2, 'listo', 211),
('CAPTACION_REDES', 'modulo', 'marketing', 'Captación en Instagram y Facebook', 'Instagram and Facebook lead capture', 'Convierte comentarios y mensajes de redes en citas: quien comenta una palabra clave recibe un privado, se le califica y se agenda la reunión o la reserva.', 'Turns social comments and messages into appointments: whoever comments a keyword gets a private message, is qualified and booked into a meeting or reservation.', array['Comentario con palabra clave: respuesta pública y mensaje privado con el entregable', 'Setter en el privado: captura 5 datos y califica', 'Agenda videollamada o lleva a la reserva', 'Respuesta a historias y mensajes directos', 'Cada lead sabe qué pieza lo trajo', 'Freno de bots: no conversa con otro agente ni en bucle', 'Reclamos y casos delicados pasan a una persona', 'Fichas de voz por marca', 'Consumo de IA y mensajería con tus propias cuentas, sin límites de cupo']::text[], array['Keyword comment: public reply and private message with the deliverable', 'Private-message setter: captures 5 data points and qualifies', 'Books a video call or leads to the reservation', 'Replies to stories and direct messages', 'Every lead knows which piece brought them', 'Bot brake: never talks to another agent or loops', 'Complaints and sensitive cases go to a person', 'Voice sheets per brand', 'AI and messaging usage on your own accounts, no quota limits']::text[], array['comentarios sin responder', 'mensajes de instagram sin respuesta', 'leads de redes', 'redes sociales sin conversion']::text[], '{}', 3500, 240, 900, 60, 0, null, 3, 'listo', 212),
('LANDINGS', 'modulo', 'marketing', 'Landings de venta por ángulo', 'Sales landing pages by angle', 'Páginas de venta que convierten tráfico en leads, con diseño, ángulo y objetivo a elegir, formulario y medición desde el primer día.', 'Sales pages that turn traffic into leads, with design, angle and goal to choose from, a form and tracking from day one.', array['10 diseños, 4 tipos, 6 ángulos de venta y 5 objetivos', 'Formulario con captura de lead y UTM', 'Logo y colores de tu marca en todas', 'Datos reales de tu catálogo, propiedades o cursos', 'Atribución: cada lead dice de qué landing y pieza llegó']::text[], array['10 designs, 4 types, 6 sales angles and 5 goals', 'Lead capture form with UTM', 'Your logo and colors on every page', 'Real data from your catalog, properties or courses', 'Attribution: every lead shows which landing and piece it came from']::text[], array['no tienen pagina de venta', 'landings', 'trafico sin conversion', 'anuncios sin destino']::text[], '{}', 1400, 60, 350, 15, 0, null, 1, 'listo', 213),
('EBOOKS', 'modulo', 'marketing', 'Ebooks y regalos digitales', 'Ebooks and digital gifts', 'Libros digitales para atraer clientes: se regalan a cambio de sus datos o se venden, con portada, PDF y EPUB listos.', 'Digital books to attract customers: given away in exchange for contact data or sold, with cover, PDF and EPUB ready.', array['Ebooks en 4 niveles, del básico sin IA al premium', 'Portada, interior, PDF y EPUB', 'Entrega como regalo con captura del lead', 'Preparado para vender en Hotmart y KDP', 'Versiones y estudio por cuenta']::text[], array['Ebooks at 4 levels, from basic without AI to premium', 'Cover, interior, PDF and EPUB', 'Delivered as a gift with lead capture', 'Ready to sell on Hotmart and KDP', 'Versions and studio per account']::text[], array['no tienen imán de clientes', 'captar leads', 'contenido de valor', 'ebook']::text[], '{}', 900, 40, 250, 10, 0, null, 1, 'listo', 214),
('SITIO_WEB', 'modulo', 'marketing', 'Sitio web editable', 'Editable website', 'Tu sitio web que cualquiera de tu equipo edita sin programar: textos y fotos con borrador, vista previa y publicación.', 'Your website that anyone on your team can edit without coding: text and photos with draft, preview and publishing.', array['Edición de textos y fotos sin programar', 'Borrador, vista previa y publicación', 'Landings y formularios conectados al CRM', 'Medición de visitas y de dónde llegan los leads']::text[], array['Edit text and photos without coding', 'Draft, preview and publishing', 'Landings and forms connected to the CRM', 'Visit tracking and lead sources']::text[], array['sitio web desactualizado', 'dependen del programador', 'presencia digital', 'pagina web']::text[], '{}', 1800, 60, 500, 15, 0, null, 2, 'listo', 215),
('COMANDANTE', 'modulo', 'direccion', 'Gerente por WhatsApp', 'WhatsApp manager', 'La dirección escribe por WhatsApp y el sistema ejecuta: busca leads, envía mensajes, cambia etapas, pausa, da de baja, deja notas y ajusta reglas del agente.', 'Management writes on WhatsApp and the system executes: finds leads, sends messages, moves stages, pauses, unsubscribes, leaves notes and adjusts agent rules.', array['Órdenes en lenguaje natural por WhatsApp', 'Buscar leads, enviar, cambiar etapa, pausar y dar de baja', 'Notas y reglas del agente desde el celular', 'Solo obedece a teléfonos de dirección, con firma de seguridad', 'Modo humano: se activa y se apaga cuando quieras']::text[], array['Natural-language orders over WhatsApp', 'Find leads, send, change stage, pause and unsubscribe', 'Notes and agent rules from your phone', 'Only obeys management phones, with security signature', 'Human mode: switch it on and off whenever you want']::text[], array['el dueno no tiene visibilidad', 'decisiones lentas', 'gerencia', 'depende de estar frente al computador']::text[], '{}', 1200, 60, 300, 20, 0, null, 2, 'listo', 216),
('INMO_SUELO', 'modulo', 'inmobiliario', 'Inteligencia de suelo y factibilidad (Quito)', 'Land intelligence and feasibility (Quito)', 'Encuentra terrenos y decide si un lote da negocio: catastro, zonificación, lotes aptos para redesarrollo, precios históricos del suelo y factibilidad.', 'Find land and decide whether a lot makes business sense: cadastre, zoning, lots suitable for redevelopment, historical land prices and feasibility.', array['Ficha del predio: catastro, zonificación y avalúo', 'Más de 8.000 lotes aptos para redesarrollo en mapa', 'Histórico de precios del suelo 2017-2025', 'Factibilidad de desarrollo con precios del Index', 'Certificado del Registro de la Propiedad leído con IA', 'Cruce de datos con tus leads y el mercado', 'Datos oficiales de Ecuador']::text[], array['Parcel sheet: cadastre, zoning and appraisal', 'Over 8,000 redevelopment-ready lots on a map', 'Land price history 2017-2025', 'Development feasibility with Index prices', 'Property Registry certificate read with AI', 'Cross-checks with your leads and the market', 'Official Ecuador data']::text[], array['inmobiliaria', 'busqueda de terrenos', 'desarrollo inmobiliario', 'valorar terrenos']::text[], '{}', 3800, 160, 1100, 30, 0, null, 3, 'listo', 217),
('COBROS', 'modulo', 'operacion', 'Cobros en línea (PayPhone)', 'Online payments (PayPhone)', 'Link de cobro con el monto exacto: al confirmarse el pago, la venta queda registrada en el lead y en la cotización.', 'Payment link with the exact amount: once payment is confirmed, the sale is recorded on the lead and the quote.', array['Link de cobro con el monto exacto y enlace estable', 'Registro automático de la venta en el lead', 'Botón Cobrar en el lead y en la cotización', 'Reembolsos y medición de reservas pagadas', 'Solo para Ecuador (PayPhone)']::text[], array['Payment link with the exact amount and a stable URL', 'Sale recorded automatically on the lead', 'Charge button on the lead and the quote', 'Refunds and tracking of paid reservations', 'Ecuador only (PayPhone)']::text[], array['cobranza manual', 'pagos lentos', 'reservas sin pago', 'cobrar a clientes']::text[], '{}', 900, 40, 250, 10, 0, null, 1, 'beta', 218),
('OBRAS', 'modulo', 'vertical', 'Seguimiento de obra con portal del cliente', 'Construction tracking with client portal', 'Controla fases, avance, bitácora, presupuesto y gasto de cada obra, y da al cliente un enlace con su avance y fotos.', 'Control phases, progress, logbook, budget and spending of every project, and give the client a link with progress and photos.', array['Fases y avance por obra', 'Bitácora con fotos', 'Presupuesto y gasto real', 'Portal público del cliente con avance y fotos', 'Presupuesto con análisis de precios unitarios']::text[], array['Phases and progress per project', 'Logbook with photos', 'Budget and actual spending', 'Public client portal with progress and photos', 'Budget with unit-price analysis']::text[], array['obras sin control', 'sobrecostos', 'cliente sin informacion de la obra', 'construccion']::text[], '{}', 2400, 100, 600, 25, 0, null, 3, 'beta', 219),
('ADMIN_RENTAS', 'modulo', 'vertical', 'Administración de rentas cortas (Airbnb)', 'Short-term rental management (Airbnb)', 'Administra propiedades de terceros: reservas, gastos, tareas, inventario y pagos, con un portal para que el propietario vea su informe.', 'Manage third-party properties: bookings, expenses, tasks, inventory and payments, with a portal so owners see their report.', array['Reservas y calendario con iCal', 'Gastos, tareas e inventario por propiedad', 'Pagos y comisión', 'Portal del propietario con su informe', 'Ocupación y rentabilidad']::text[], array['Bookings and calendar with iCal', 'Expenses, tasks and inventory per property', 'Payments and commission', 'Owner portal with their report', 'Occupancy and profitability']::text[], array['administrar airbnb', 'propiedades de terceros', 'propietarios sin informacion', 'renta corta']::text[], '{}', 1800, 90, 450, 20, 0, null, 2, 'beta', 220),
('ACADEMY', 'modulo', 'vertical', 'Academia de cursos propia', 'Your own course academy', 'Vende cursos con tu marca: fábrica de cursos, landings, diagnóstico, seguimiento por WhatsApp y cobro.', 'Sell courses under your brand: course factory, landings, diagnostics, WhatsApp follow-up and payments.', array['Una plantilla, muchos cursos', 'Landings por curso', 'Diagnóstico por puntos sin IA', 'Pipeline y seguimiento por WhatsApp', 'Ebooks gratis como imán de clientes', 'Cobro en línea']::text[], array['One template, many courses', 'Landing page per course', 'Points-based diagnostic without AI', 'Pipeline and WhatsApp follow-up', 'Free ebooks as lead magnets', 'Online payments']::text[], array['vender cursos', 'capacitacion online', 'academia', 'educacion']::text[], '{}', 3200, 150, 800, 40, 0, null, 4, 'beta', 221),
('LICENCIA', 'servicio', 'consultoria', 'CRM en tu propia infraestructura (licencia)', 'CRM on your own infrastructure (license)', 'Instalamos el sistema en tu propio Supabase, Vercel y n8n, con tus datos aparte y soporte con actualizaciones.', 'We install the system on your own Supabase, Vercel and n8n, with your data kept separate, plus support and updates.', array['Instalación en tu propia nube', 'Tus datos separados por completo', 'Identidad de tu empresa configurable', 'Soporte y actualizaciones por versión', 'Contrato de licencia y soporte']::text[], array['Installation in your own cloud', 'Fully separated data', 'Configurable company identity', 'Support and updates by version', 'License and support contract']::text[], array['datos aparte', 'cadena de empresas', 'soberania de datos']::text[], '{}', 3500, 250, 1000, 60, 0, null, 2, 'proximamente', 222)
on conflict (codigo) do nothing;

update catalogo set habilidades_es = array['Freno de bots: si quien escribe es otro agente, deja de contestar y avisa', 'Control de citas: nunca confirma una cita que no existe; si falta el evento, lo crea', 'Supervisor en vivo antes de enviar: sin cierres pasivos, con horas correctas de Quito', 'Cada lead llega con el anuncio o pieza que lo trajo', 'Escalamiento inmediato a una persona cuando el lead pide llamada', 'Una sola voz de instrucciones, probada con 40 casos reales', 'La ficha del lead solo se completa: nunca se reescribe ni se borra', 'Las respuestas automáticas de otros negocios no cuentan como respuesta del lead']::text[], habilidades_en = array['Bot brake: if the sender is another agent, it stops replying and alerts you', 'Appointment control: never confirms an appointment that does not exist; creates the event if missing', 'Live supervisor before sending: no passive closings, correct Quito times', 'Every lead arrives with the ad or piece that brought them', 'Immediate escalation to a person when the lead asks for a call', 'A single set of instructions, tested on 40 real cases', 'The lead record is only completed: never rewritten or deleted', 'Auto-replies from other businesses do not count as a lead reply']::text[] where codigo = 'IAGENTE_WA';
update catalogo set habilidades_es = array['Pantalla Hoy: alertas urgentes y acciones del día', 'Pantallas que se refrescan solas en vivo', 'Pipeline que se mueve solo con la actividad real del lead', 'Clasificación única de leads con reclasificación desde la actividad', 'Cada lead guarda su anuncio y la pieza de origen', 'Interruptores para encender y apagar cada automatización', 'Cada término tiene su ayuda y cada resultado se explica solo', 'Ningún número lo inventa un modelo de IA: cada cifra muestra su origen']::text[], habilidades_en = array['Today screen: urgent alerts and actions of the day', 'Screens that refresh live on their own', 'Pipeline that moves by itself with real lead activity', 'Single lead classification with reclassification from activity', 'Every lead stores its ad and source piece', 'Switches to turn each automation on and off', 'Every term has help and every result explains itself', 'No number is invented by an AI model: every figure shows its source']::text[] where codigo = 'CRM_BASICO';
update catalogo set habilidades_es = array['Seguimiento perpetuo: nunca suelta un lead hasta la baja o la venta', 'Cotizaciones guardadas en la ficha, con total en efectivo y tarjeta aparte', 'Lista de precios única que gobierna agente, sitio, cotizaciones y PDF', 'Vigía de precios: avisa si algún precio visible no cuadra', 'Aviso a los 10 minutos si un lead que escribió sigue sin respuesta', 'Trazabilidad por mensaje: enviado, entregado, leído y respondido', 'Aprendizaje diario que propone mejoras con aprobación']::text[], habilidades_en = array['Perpetual follow-up: never drops a lead until opt-out or sale', 'Quotes saved on the record, with cash total and card shown separately', 'Single price list governing agent, site, quotes and PDF', 'Price watchdog: alerts if any visible price does not match', 'Alert after 10 minutes if a lead who wrote still has no reply', 'Per-message traceability: sent, delivered, read and replied', 'Daily learning that proposes improvements with approval']::text[] where codigo = 'CRM_OPERATIVO';
update catalogo set habilidades_es = array['Gerente por WhatsApp: la dirección ordena desde el celular', 'Registro de reuniones con la dirección: transcripción, decisiones y tareas', 'Avisos por niveles: campana, WhatsApp y llamada del gerente según la gravedad', 'Panel de control con interruptores por automatización', 'Seguridad por empresa: cada una ve solo lo suyo', 'Atribución pieza, lead y venta para medir qué marketing trae clientes']::text[], habilidades_en = array['WhatsApp manager: management gives orders from their phone', 'Meeting log with management: transcript, decisions and tasks', 'Tiered alerts: bell, WhatsApp and manager call by severity', 'Control panel with a switch per automation', 'Per-company security: each sees only its own data', 'Piece, lead and sale attribution to measure which marketing brings customers']::text[] where codigo = 'CRM_GERENCIAL';
update catalogo set habilidades_es = array['Nutrición perpetua: a los 30, 60 y 90 días y luego cada 45, sin soltar al lead', 'Baja suave: la primera pausa 45 días; la segunda es definitiva, para cuidar el número', 'Ventana de envío de 8:00 a 22:00 en oleadas, con un minuto fijo por lead', '53 plantillas aprobadas por Meta, con audio, imagen, video y PDF', 'Fallas de entrega resueltas solas, con el motivo real y qué hacer', 'Rastro por mensaje: enviado, entregado, leído y respondido', 'Panel de control: vencidos, reprogramar, cancelar y reactivar', 'Conversaciones en modo humano liberadas a las 48 h', 'Seguimiento posterior a la videollamada, nunca antes de la cita', 'Aprendizaje diario que mide y propone reglas de bajo riesgo', 'Pantalla Qué está funcionando por etapa']::text[], habilidades_en = array['Perpetual nurture: at 30, 60 and 90 days and then every 45, never dropping the lead', 'Soft opt-out: the first pauses 45 days; the second is permanent, protecting your number', 'Send window 8:00 to 22:00 in waves, with a fixed minute per lead', '53 Meta-approved templates, with audio, image, video and PDF', 'Delivery failures resolved automatically, with the real reason and what to do', 'Per-message trail: sent, delivered, read and replied', 'Control panel: overdue, reschedule, cancel and reactivate', 'Human-mode conversations released after 48 h', 'Post-video-call follow-up, never before the appointment', 'Daily learning that measures and proposes low-risk rules', 'What is working screen by stage']::text[] where codigo = 'SEGUIMIENTOS';
update catalogo set habilidades_es = array['Búsqueda con fuentes citadas, sin raspar portales', 'Cruce con catastro y SRI', 'Cada dato guarda su origen y su base legal', 'Predios con avalúo y trámites oficiales', 'Certificado del Registro de la Propiedad leído con IA', 'Radar de referentes y de competencia por la vía oficial de Meta']::text[], habilidades_en = array['Search with cited sources, no portal scraping', 'Cross-check with cadastre and tax registry', 'Every data point stores its source and legal basis', 'Parcels with appraisal and official procedures', 'Property Registry certificate read with AI', 'Referent and competitor radar through the official Meta channel']::text[] where codigo = 'PROSPECCION';
update catalogo set habilidades_es = array['Cotización guardada completa en la ficha del lead', 'Total en efectivo y tarjeta aparte, con su porcentaje', 'PDF con tablas y pie numerado', 'Una sola lista de precios para toda la empresa', 'Cotizador público que crea el lead con su origen', 'Reserva con cobro y descuento incluido en la cotización', 'Lo que falta se marca A CONFIRMAR: nunca un precio inventado']::text[], habilidades_en = array['Complete quote saved on the lead record', 'Cash total and card shown separately, with its percentage', 'PDF with tables and numbered footer', 'A single price list for the whole company', 'Public quoting tool that creates the lead with its source', 'Reservation with payment and discount built into the quote', 'Missing items are marked TO CONFIRM: never an invented price']::text[] where codigo = 'COTIZADOR';
update catalogo set habilidades_es = array['Plan del mes por cuenta, para aprobar', 'Comparación con la competencia', 'Producción continua: mantiene 7 días de agenda llena', 'Calendario y aprobación humana de cada pieza', 'Noticias del día convertidas en contenido', 'Ficha de cada pieza: quién, para qué, cómo se hizo y resultado', 'Semáforo de viralidad contra tu propia mediana', 'Qué piezas traen clientes: de la pieza al lead y a la venta', 'Marcas y líneas con reglas fijas por cuenta', 'Control de costos por pieza y por mes']::text[], habilidades_en = array['Monthly plan per account, for approval', 'Comparison with competitors', 'Continuous production: keeps 7 days of agenda full', 'Calendar and human approval of every piece', 'Daily news turned into content', 'Piece record: who, why, how it was made and result', 'Virality traffic light against your own median', 'Which pieces bring customers: from piece to lead to sale', 'Brands and lines with fixed rules per account', 'Cost control per piece and per month']::text[] where codigo = 'MARKETING';
update catalogo set habilidades_es = array['Plan con 4 destinos y 7 formatos de creativo, con aprobación previa', 'Nada gasta sin tu visto bueno', 'Anuncio a partir de una publicación orgánica', 'Selector entre tus cuentas de Meta, páginas, Instagram y píxel', 'Catálogo de anuncios: confirma producto y precio de cada uno', 'Resultados por anuncio: gasto, leads y costo por lead', 'Foto diaria de Meta: seguidores, pauta y alcance', 'Píxel y eventos compartidos entre navegador y servidor', 'Piezas de anuncio vectoriales: 4 formatos y 10 estilos, con el texto en trazados']::text[], habilidades_en = array['Plan with 4 destinations and 7 creative formats, with prior approval', 'Nothing spends without your approval', 'Ad built from an organic post', 'Selector across your Meta accounts, pages, Instagram and pixel', 'Ad catalog: confirm product and price of each one', 'Results per ad: spend, leads and cost per lead', 'Daily Meta snapshot: followers, spend and reach', 'Pixel and events shared between browser and server', 'Vector ad pieces: 4 formats and 10 styles, with text as outlines']::text[] where codigo = 'ADSBOOM';
update catalogo set habilidades_es = array['Banco de plantillas: promesa de compraventa, corretaje y arriendo', 'Certificado del Registro de la Propiedad leído con IA', 'Avalúo con normativa del Municipio y comparables automáticos', 'Si falla la tabla, vuelve a las plantillas base']::text[], habilidades_en = array['Template bank: sale promise, brokerage and lease', 'Property Registry certificate read with AI', 'Appraisal with municipal rules and automatic comparables', 'If the table fails, it falls back to base templates']::text[] where codigo = 'DOCUMENTOS';
update catalogo set habilidades_es = array['Aviso a los 10 minutos cuando un lead que escribió no tiene respuesta', 'Recordatorio de cita 30 minutos antes, con nota interna', 'Vigía de precios: contra la lista única de toda la empresa', 'Resumen crítico del día en una sola llamada', 'Avisos de error a la campana y a WhatsApp']::text[], habilidades_en = array['Alert after 10 minutes when a lead who wrote has no reply', 'Appointment reminder 30 minutes before, with internal note', 'Price watchdog: against the company-wide single list', 'Critical daily summary in a single call', 'Error alerts to the bell and WhatsApp']::text[] where codigo = 'VIGIA';
update catalogo set habilidades_es = array['13 interruptores para encender y apagar cada automatización', 'Cada término tiene su ayuda y cada pantalla se interpreta sola', 'Cada número muestra su origen o dice que falta el dato', 'Base cerrada a la llave pública y aislada por empresa', 'Webhooks con firma y límite de peticiones por IP', 'Cada incidencia viene con su solución']::text[], habilidades_en = array['13 switches to turn each automation on and off', 'Every term has help and every screen interprets itself', 'Every number shows its source or says data is missing', 'Database closed to the public key and isolated per company', 'Signed webhooks and per-IP request limit', 'Every incident comes with its fix']::text[] where codigo = 'PANEL';
update catalogo set habilidades_es = array['Una persona, una cita: al reagendar se borra la anterior', 'El calendario del agente pasa al CRM y avisa a dirección', 'Estado visible en la agenda: POR CONFIRMAR o CONFIRMADA', 'Si se borra la cita de alguien que no pidió cambiarla, se restaura y avisa', 'Agenda automática desde la página: elige horario libre y avisa por WhatsApp']::text[], habilidades_en = array['One person, one appointment: rescheduling deletes the previous one', 'The agent calendar flows into the CRM and alerts management', 'Visible status on the agenda: TO CONFIRM or CONFIRMED', 'If someone who did not ask to change is deleted, it is restored and alerts', 'Automatic scheduling from the page: picks a free slot and notifies on WhatsApp']::text[] where codigo = 'CITAS';
update catalogo set habilidades_es = array['Llamadas críticas del gerente a dirección, agrupadas en una al día', 'Si no contesta, aviso por WhatsApp', 'Todo queda en el registro de reuniones', 'Nunca llama a números de demostración']::text[], habilidades_en = array['Critical manager calls to management, grouped into one per day', 'If unanswered, a WhatsApp alert follows', 'Everything is saved in the meeting log', 'Never calls demo numbers']::text[] where codigo = 'LLAMADAS';
